/* ============================================================
   我在看着你 · 配套脚本（if love）
   1. 每次打开酒馆随机换一张背景（不会连着两次同一张）
   2. 正文里随机几个字瞬间变成红色「？」再变回去
   放进酒馆助手的全局脚本即可；只改下面 CONFIG。
   ============================================================ */
(() => {
    const CONFIG = {
        randomBg: true,                              // 随机背景
        bgList: ['R1', 'R2', 'R3', 'R4', 'R5'],      // 不想要哪张就删掉
        qGlitch: true,                               // 字变「？」
        qEvery: 1400,                                // 多久闪一次（毫秒）
        qCount: 4,                                   // 每次换几个字
        qRecentMessages: 3,                          // 只在最后几条消息里闪
    };

    // 酒馆助手的脚本跑在 iframe 里，要操作酒馆本体的页面
    const win = (() => { try { return window.parent && window.parent.document ? window.parent : window; } catch (e) { return window; } })();
    const doc = win.document;

    // 保证红色问号独立生效，不依赖主题 CSS。
    const qStyle = doc.createElement('style');
    qStyle.textContent = '.th-qq { color: #A3262C !important; }';
    if (CONFIG.qGlitch) (doc.head || doc.documentElement).appendChild(qStyle);
    const KEY = 'ifloveWatchingYouLastBg';

    /* ---------- 1. 随机背景 ---------- */
    if (CONFIG.randomBg && CONFIG.bgList.length) {
        let last = null;
        try { last = win.localStorage.getItem(KEY); } catch (e) { /* 读不到就算了 */ }
        const pool = CONFIG.bgList.length > 1 ? CONFIG.bgList.filter(k => k !== last) : CONFIG.bgList;
        const k = pool[Math.floor(Math.random() * pool.length)];
        doc.documentElement.style.setProperty('--thBgA', `var(--thBg${k}a)`);
        doc.documentElement.style.setProperty('--thBgB', `var(--thBg${k}b)`);
        try { win.localStorage.setItem(KEY, k); } catch (e) { /* 存不了就算了 */ }
    }

    /* ---------- 2. 字变「？」 ---------- */
    const live = new Set();
    const CJK = /[一-鿿]/;

    function generating() {
        const stop = doc.getElementById('mes_stop');
        return !!stop && win.getComputedStyle(stop).display !== 'none';
    }

    function textNodes(root) {
        const out = [];
        const w = doc.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
            acceptNode(n) {
                const p = n.parentElement;
                if (!p || p.closest('pre, code, .th-qq, textarea, script, style')) return NodeFilter.FILTER_REJECT;
                return CJK.test(n.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
            },
        });
        while (w.nextNode()) out.push(w.currentNode);
        return out;
    }

    function restore(span) {
        if (!live.has(span)) return;
        live.delete(span);
        if (!span.isConnected) return;
        const parent = span.parentNode;
        parent.replaceChild(doc.createTextNode(span.dataset.o), span);
        parent.normalize();
    }

    function flick() {
        const all = [...doc.querySelectorAll('#chat .mes')];
        let mesList = all.slice(-CONFIG.qRecentMessages);
        if (generating()) mesList = mesList.filter(m => !m.classList.contains('last_mes'));
        const roots = mesList
            .filter(m => !m.querySelector('.edit_textarea'))
            .map(m => m.querySelector('.mes_text'))
            .filter(Boolean);
        const nodes = roots.flatMap(textNodes);
        if (!nodes.length) return;

        for (let i = 0; i < CONFIG.qCount; i++) {
            const node = nodes[Math.floor(Math.random() * nodes.length)];
            if (!node.isConnected) continue;
            const chars = [...node.nodeValue];
            const idx = chars.map((c, j) => (CJK.test(c) ? j : -1)).filter(j => j >= 0);
            if (!idx.length) continue;
            const j = idx[Math.floor(Math.random() * idx.length)];
            const before = chars.slice(0, j).join('');
            const after = chars.slice(j + 1).join('');
            const span = doc.createElement('span');
            span.className = 'th-qq';
            span.dataset.o = chars[j];
            span.textContent = '？';
            const frag = doc.createDocumentFragment();
            if (before) frag.appendChild(doc.createTextNode(before));
            frag.appendChild(span);
            if (after) frag.appendChild(doc.createTextNode(after));
            node.parentNode.replaceChild(frag, node);
            live.add(span);
            setTimeout(() => restore(span), 380 + Math.random() * 400);
            // 这个文本节点已经被拆开，后面的循环换别的节点
            nodes.splice(nodes.indexOf(node), 1);
            if (!nodes.length) break;
        }
    }

    let timer = null;
    if (CONFIG.qGlitch) timer = setInterval(flick, CONFIG.qEvery);

    // 脚本被关掉时，把正在显示的「？」都换回原字
    const cleanup = () => {
        if (timer) clearInterval(timer);
        [...live].forEach(restore);
        qStyle.remove();
    };
    window.addEventListener('pagehide', cleanup);
    window.addEventListener('unload', cleanup);
})();
